css:
.hrai-sim-container {
    padding: 28px;
    background: #f4f5f7;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
    line-height: 1.45;
}

.hrai-sim-container .hrai-sim-header {
    background: #1a2744;
    color: #f4f5f7;
    padding: 28px 32px;
    border-left: 6px solid #c9a14a;
    margin-bottom: 24px;
    border-radius: 2px;
}
.hrai-sim-container .hrai-sim-header-eyebrow {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    color: #c9a14a;
    margin-bottom: 8px;
    font-weight: 600;
}
.hrai-sim-container .hrai-sim-header h1 {
    font-size: 1.7rem;
    margin: 0 0 6px 0;
    font-weight: 600;
    letter-spacing: -0.01em;
}
.hrai-sim-container .hrai-sim-header-sub {
    font-size: 0.92rem;
    color: #b8c2d4;
    font-weight: 400;
}

.hrai-sim-container .hrai-sim-period-strip {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-radius: 2px;
    padding: 16px 24px;
    margin-bottom: 20px;
    display: flex;
    align-items: center;
    gap: 28px;
}
.hrai-sim-container .hrai-sim-period-block {
    display: flex;
    flex-direction: column;
    border-right: 1px solid #d8dde6;
    padding-right: 28px;
}
.hrai-sim-container .hrai-sim-period-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #6b7689;
    font-weight: 600;
    margin-bottom: 4px;
}
.hrai-sim-container .hrai-sim-period-value {
    font-size: 1.25rem;
    font-weight: 700;
    color: #1a2744;
}
.hrai-sim-container .hrai-sim-period-title {
    font-size: 1.05rem;
    font-weight: 600;
    color: #1a2744;
}

.hrai-sim-container .hrai-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.hrai-sim-container .hrai-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #d8dde6;
    padding: 18px 20px;
    border-radius: 2px;
    border-top: 3px solid #6b7689;
}
.hrai-sim-container .hrai-kpi-score {
    border-top-color: #c9a14a;
    background: linear-gradient(180deg, #ffffff 0%, #fbf6e8 100%);
}
.hrai-sim-container .hrai-sim-kpi-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #6b7689;
    font-weight: 600;
    margin-bottom: 8px;
}
.hrai-sim-container .hrai-sim-kpi-value {
    font-size: 2.2rem;
    font-weight: 700;
    color: #1a2744;
    line-height: 1.1;
}
.hrai-sim-container .hrai-kpi-score .hrai-sim-kpi-value {
    color: #8c6f1f;
}
.hrai-sim-container .hrai-sim-kpi-sub {
    font-size: 0.75rem;
    color: #6b7689;
    margin-top: 4px;
}

.hrai-sim-container .hrai-sim-cabinet-strip {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-radius: 2px;
    padding: 18px 22px;
    margin-bottom: 24px;
}
.hrai-sim-container .hrai-sim-cabinet-title {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #6b7689;
    font-weight: 600;
    margin-bottom: 14px;
}
.hrai-sim-container .hrai-sim-cabinet-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 14px;
}
.hrai-sim-container .hrai-sim-cabinet-card {
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.hrai-sim-container .hrai-sim-cab-name {
    font-size: 0.82rem;
    font-weight: 600;
    color: #1a2744;
}
.hrai-sim-container .hrai-sim-cab-bar {
    height: 8px;
    background: #e6ebf2;
    border-radius: 4px;
    overflow: hidden;
}
.hrai-sim-container .hrai-sim-cab-fill {
    height: 100%;
    width: 50%;
    background: linear-gradient(90deg, #4a6a8a, #1a2744);
    transition: width 0.4s ease, background 0.4s ease;
}
.hrai-sim-container .hrai-sim-cab-pct {
    font-size: 0.78rem;
    color: #6b7689;
    font-weight: 600;
}

.hrai-sim-container .hrai-sim-briefing {
    background: #fbf6e8;
    border-left: 4px solid #c9a14a;
    padding: 20px 24px;
    margin-bottom: 24px;
    border-radius: 2px;
}
.hrai-sim-container .hrai-sim-briefing-title {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #8c6f1f;
    font-weight: 700;
    margin-bottom: 10px;
}
.hrai-sim-container .hrai-sim-briefing-body {
    font-size: 0.95rem;
    color: #1a2744;
    line-height: 1.6;
}

.hrai-sim-container .hrai-sim-controls {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-radius: 2px;
    padding: 24px 28px;
    margin-bottom: 24px;
}
.hrai-sim-container .hrai-sim-controls h3 {
    font-size: 1.1rem;
    font-weight: 700;
    margin: 0 0 8px 0;
    color: #1a2744;
    border-bottom: 2px solid #c9a14a;
    padding-bottom: 8px;
    display: inline-block;
}
.hrai-sim-container .hrai-sim-instructions {
    font-size: 0.88rem;
    color: #4a5468;
    margin: 14px 0 20px 0;
}

.hrai-sim-container .hrai-sim-pilot-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 10px;
}
.hrai-sim-container .hrai-sim-pilot-row {
    display: grid;
    grid-template-columns: 36px 1fr 220px;
    gap: 14px;
    align-items: center;
    padding: 12px 14px;
    background: #f8f9fb;
    border: 1px solid #e1e6ee;
    border-radius: 2px;
}
.hrai-sim-container .hrai-sim-pilot-num {
    font-size: 0.85rem;
    font-weight: 700;
    color: #c9a14a;
    text-align: center;
}
.hrai-sim-container .hrai-sim-pilot-info {
    display: flex;
    flex-direction: column;
    gap: 2px;
}
.hrai-sim-container .hrai-sim-pilot-name {
    font-size: 0.92rem;
    font-weight: 600;
    color: #1a2744;
}
.hrai-sim-container .hrai-sim-pilot-meta {
    font-size: 0.78rem;
    color: #6b7689;
}

.hrai-sim-container .hrai-sim-matrix-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 8px;
}
.hrai-sim-container .hrai-sim-matrix-row {
    display: grid;
    grid-template-columns: 36px 1fr 220px;
    gap: 14px;
    align-items: center;
    padding: 10px 14px;
    background: #f8f9fb;
    border: 1px solid #e1e6ee;
    border-radius: 2px;
}
.hrai-sim-container .hrai-sim-matrix-cat {
    font-size: 0.9rem;
    font-weight: 500;
    color: #1a2744;
}

.hrai-sim-container .hrai-sim-select,
.hrai-sim-container select.hrai-sim-pilot-select,
.hrai-sim-container select.hrai-sim-matrix-select {
    background-color: #ffffff;
    color: #1a2744;
    border: 1px solid #b6bfd0;
    border-radius: 2px;
    padding: 7px 10px;
    font-size: 0.86rem;
    width: 100%;
    cursor: pointer;
}
.hrai-sim-container select.hrai-sim-pilot-select option,
.hrai-sim-container select.hrai-sim-matrix-select option,
.hrai-sim-container .hrai-sim-select option {
    background-color: #ffffff;
    color: #1a2744;
}
.hrai-sim-container .hrai-sim-select:focus,
.hrai-sim-container select:focus,
.hrai-sim-container input:focus {
    outline: 2px solid #c9a14a;
    outline-offset: 1px;
}

.hrai-sim-container .hrai-sim-r3-section {
    margin-bottom: 22px;
    padding-bottom: 18px;
    border-bottom: 1px dashed #d8dde6;
}
.hrai-sim-container .hrai-sim-r3-section:last-child {
    border-bottom: none;
    padding-bottom: 0;
    margin-bottom: 0;
}
.hrai-sim-container .hrai-sim-r3-label {
    display: block;
    font-size: 0.92rem;
    font-weight: 600;
    color: #1a2744;
    margin-bottom: 12px;
}
.hrai-sim-container .hrai-sim-checkbox-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 10px;
}
.hrai-sim-container .hrai-sim-check {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    background: #f8f9fb;
    border: 1px solid #e1e6ee;
    padding: 10px 12px;
    border-radius: 2px;
    font-size: 0.86rem;
    color: #1a2744;
    cursor: pointer;
    margin: 0;
}
.hrai-sim-container .hrai-sim-check input[type="checkbox"] {
    margin-top: 2px;
    accent-color: #1a2744;
}

.hrai-sim-container .hrai-sim-action-row {
    display: flex;
    gap: 12px;
    align-items: center;
    margin-bottom: 28px;
}
.hrai-sim-container .hrai-sim-btn-primary {
    background: #1a2744;
    border: 1px solid #1a2744;
    color: #f4f5f7;
    font-weight: 600;
    padding: 11px 28px;
    border-radius: 2px;
    font-size: 0.92rem;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    transition: background 0.2s ease;
}
.hrai-sim-container .hrai-sim-btn-primary:hover {
    background: #c9a14a;
    border-color: #c9a14a;
    color: #1a2744;
}
.hrai-sim-container .hrai-sim-btn-secondary {
    border: 1px solid #b6bfd0;
    color: #4a5468;
    background: #ffffff;
    border-radius: 2px;
    padding: 9px 18px;
    font-size: 0.82rem;
}

.hrai-sim-container .hrai-sim-history,
.hrai-sim-container .hrai-sim-chart {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-radius: 2px;
    padding: 22px 26px;
    margin-bottom: 24px;
}
.hrai-sim-container .hrai-sim-section-title {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #6b7689;
    font-weight: 700;
    margin-bottom: 14px;
}
.hrai-sim-container .hrai-sim-history table {
    margin-bottom: 0;
    font-size: 0.86rem;
}
.hrai-sim-container .hrai-sim-history th {
    background: #1a2744;
    color: #f4f5f7;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    padding: 10px 12px;
    border: none;
}
.hrai-sim-container .hrai-sim-history td {
    padding: 10px 12px;
    border-bottom: 1px solid #e6ebf2;
    color: #1a2744;
}
.hrai-sim-container .hrai-sim-chart canvas {
    max-height: 320px;
}

@media (max-width: 768px) {
    .hrai-sim-container { padding: 16px; }
    .hrai-sim-container .hrai-sim-header { padding: 20px; }
    .hrai-sim-container .hrai-sim-header h1 { font-size: 1.3rem; }
    .hrai-sim-container .hrai-sim-period-strip { flex-direction: column; align-items: flex-start; gap: 10px; }
    .hrai-sim-container .hrai-sim-period-block { border-right: none; padding-right: 0; }
    .hrai-sim-container .hrai-sim-pilot-row,
    .hrai-sim-container .hrai-sim-matrix-row {
        grid-template-columns: 1fr;
        gap: 8px;
    }
    .hrai-sim-container .hrai-sim-kpi-value { font-size: 1.6rem; }
}

/* v1.1.0 additions: accessible focus ring + completion summary */
.hrai-sim-container :is(select, input, button, textarea):focus-visible { outline: 3px solid #2f6f4f; outline-offset: 2px; }
.hrai-completion { padding: 8px 4px; text-align: center; }
.hrai-completion-title { margin: 0 0 12px; font-size: 1.4rem; }
.hrai-completion-score { margin: 6px 0 16px; }
.hrai-completion-score .acs-num { font-size: 2.6rem; font-weight: 700; }
.hrai-completion-score .acs-max { font-size: 1.1rem; opacity: .7; margin-left: 2px; }
.hrai-completion-score .acs-cap { font-size: .72rem; text-transform: uppercase; letter-spacing: .06em; opacity: .7; margin-top: 2px; }
.hrai-completion-rating { margin: 8px auto 14px; max-width: 580px; line-height: 1.5; font-weight: 600; }
.hrai-completion-takeaways { text-align: left; max-width: 660px; margin: 6px auto 0; }
.hrai-completion-takeaways h4 { font-size: .95rem; margin: 0 0 8px; }
.hrai-completion-takeaways ul { margin: 0; padding-left: 20px; }
.hrai-completion-takeaways li { margin-bottom: 6px; line-height: 1.45; }
.hrai-completion-thanks { font-size: .85rem; opacity: .75; margin-top: 16px; }

