                { num: 7,  key: 'p7',  defensible: 'rescope', crit: true,  meta: 'ServiceNow + ES-LLM layer · USD 0.5M · Ileana · live CR · ticket load −38% · CR retirement-fund misanswer triggered formal complaint' },
