                { num: 11, key: 'p11', defensible: 'kill',    crit: true,  meta: 'CR startup (Esteban brother-in-law) · USD 0.3M · UNSANCTIONED · GDPR-equivalent exposure ES · no employee consent · conflict of interest' }
            ];

            this.MATRIX = [
                { num: 1,  key: 'm1',  defensible: 'led',  meta: 'Recruiting — top-of-funnel sourcing & screening' },
                { num: 2,  key: 'm2',  defensible: 'led',  meta: 'Recruiting — middle-of-funnel candidate engagement' },
                { num: 3,  key: 'm3',  defensible: 'aug',  meta: 'Recruiting — offer-stage construction & negotiation' },
                { num: 4,  key: 'm4',  defensible: 'led',  meta: 'Onboarding — administrative provisioning' },
                { num: 5,  key: 'm5',  defensible: 'human',meta: 'Onboarding — cultural integration & first-90-days' },
                { num: 6,  key: 'm6',  defensible: 'aug',  meta: 'Performance — narrative drafting' },
                { num: 7,  key: 'm7',  defensible: 'aug',  meta: 'Performance — calibration discussions' },
                { num: 8,  key: 'm8',  defensible: 'aug',  meta: 'Compensation — modelling & decision support' },
                { num: 9,  key: 'm9',  defensible: 'human',meta: 'Compensation — final pay decision authority' },
                { num: 10, key: 'm10', defensible: 'aug',  meta: 'Manager enablement — feedback synthesis' },
                { num: 11, key: 'm11', defensible: 'led',  meta: 'Employee Q&A — policy & benefits (Tier 1)' },
                { num: 12, key: 'm12', defensible: 'human',meta: 'Employee escalations (Tier 2/3) — grievances, ER' },
                { num: 13, key: 'm13', defensible: 'aug',  meta: 'Terminations — case preparation & documentation' },
                { num: 14, key: 'm14', defensible: 'human',meta: 'Terminations — execution conversation' },
                { num: 15, key: 'm15', defensible: 'led',  meta: 'Learning — content curation & path recommendation' },
                { num: 16, key: 'm16', defensible: 'aug',  meta: 'Learning — coaching interactions' },
                { num: 17, key: 'm17', defensible: 'led',  meta: 'Exit interviews — synthesis & theme extraction' },
                { num: 18, key: 'm18', defensible: 'led',  meta: 'Retention — risk modelling & alerting' },
                { num: 19, key: 'm19', defensible: 'aug',  meta: 'Internal mobility — recommendations & matching' }
            ];

            this.ROUND_TITLES = ['r1_title', 'r2_title', 'r3_title'];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    auditScore: 0,
                    matrixScore: 0,
                    archScore: 0,
                    totalScore: 0,
                    ceoSupport: 50,
                    cooSupport: 50,
                    cfoSupport: 50,
                    boardSupport: 50,
                    councilSupport: 50,
                    scoreHistory: [],
                    ceoHistory: [],
                    cooHistory: [],
                    cfoHistory: [],
                    boardHistory: [],
                    councilHistory: [],
                    pilots: {},
                    matrix: {},
                    vendorArch: '',
                    buildEnvelope: [],
                    changePlan: [],
                    lastFeedback: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = { round: 1, summary: '' };
            }
            this._renderInputs();
            this._updateBriefing(state);
            this._updateCabinetBars(state.domainState);
        }

        _renderInputs() {
            var pilotGrid = document.getElementById('pilotGrid');
            if (pilotGrid && pilotGrid.children.length === 0) {
                var html = '';
                for (var i = 0; i < this.PILOTS.length; i++) {
                    var p = this.PILOTS[i];
                    html += '<div class="hrai-sim-pilot-row">';
                    html += '<div class="hrai-sim-pilot-num">#' + p.num + '</div>';
                    html += '<div class="hrai-sim-pilot-info">';
                    html += '<div class="hrai-sim-pilot-name" data-i18n="pilot_' + p.num + '_name"></div>';
                    html += '<div class="hrai-sim-pilot-meta">' + p.meta + '</div>';
                    html += '</div>';
                    html += '<select class="hrai-sim-pilot-select" id="pilot_' + p.num + '">';
                    html += '<option value="" data-i18n="opt_choose">— choose —</option>';
                    html += '<option value="kill" data-i18n="opt_kill">Kill</option>';
                    html += '<option value="scale" data-i18n="opt_scale">Scale</option>';
                    html += '<option value="rescope" data-i18n="opt_rescope">Re-scope</option>';
                    html += '<option value="hold" data-i18n="opt_hold">Hold pending review</option>';
                    html += '</select>';
                    html += '</div>';
                }
                pilotGrid.innerHTML = html;
            }

            var matrixGrid = document.getElementById('matrixGrid');
            if (matrixGrid && matrixGrid.children.length === 0) {
                var mhtml = '';
                for (var j = 0; j < this.MATRIX.length; j++) {
                    var m = this.MATRIX[j];
                    mhtml += '<div class="hrai-sim-matrix-row">';
                    mhtml += '<div class="hrai-sim-pilot-num">' + m.num + '</div>';
                    mhtml += '<div class="hrai-sim-matrix-cat" data-i18n="cat_' + m.num + '">' + m.meta + '</div>';
                    mhtml += '<select class="hrai-sim-matrix-select" id="cat_' + m.num + '">';
                    mhtml += '<option value="" data-i18n="opt_choose">— choose —</option>';
                    mhtml += '<option value="led" data-i18n="opt_led">Agent-led</option>';
                    mhtml += '<option value="aug" data-i18n="opt_aug">Agent-augmented</option>';
                    mhtml += '<option value="human" data-i18n="opt_human">Human-only</option>';
                    mhtml += '</select>';
                    mhtml += '</div>';
                }
                matrixGrid.innerHTML = mhtml;
            }
        }

        validateDecisions(decisions) {
            var period = (window.mySimulation.state.currentPeriod) || 1;
            decisions.round = period;

            if (period === 1) {
                var allSet = true;
                var pilotChoices = {};
                for (var i = 0; i < this.PILOTS.length; i++) {
                    var p = this.PILOTS[i];
                    var sel = document.getElementById('pilot_' + p.num);
                    if (!sel || !sel.value) { allSet = false; break; }
                    pilotChoices[p.num] = sel.value;
                }
                if (!allSet) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_all_pilots'), 'warning'
                    );
                    return false;
                }
                decisions.pilotChoices = pilotChoices;
                return true;
            }

            if (period === 2) {
                var allSetM = true;
                var matrixChoices = {};
                for (var j = 0; j < this.MATRIX.length; j++) {
                    var m = this.MATRIX[j];
                    var ms = document.getElementById('cat_' + m.num);
                    if (!ms || !ms.value) { allSetM = false; break; }
                    matrixChoices[m.num] = ms.value;
                }
                if (!allSetM) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_all_matrix'), 'warning'
                    );
                    return false;
                }
                decisions.matrixChoices = matrixChoices;
                return true;
            }

            if (period === 3) {
                var vsel = document.getElementById('vendorArchSelect');
                if (!vsel || !vsel.value) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_vendor'), 'warning'
                    );
                    return false;
                }
                decisions.vendorArch = vsel.value;

                var buildIds = ['buildPerf','buildBenefits','buildOnboarding','buildCalibration','buildExit','buildEthics','buildMobility','buildSafety'];
                var build = [];
                for (var k = 0; k < buildIds.length; k++) {
                    var c = document.getElementById(buildIds[k]);
                    if (c && c.checked) build.push(c.value);
                }
                decisions.buildEnvelope = build;

                var cpIds = ['cpRecruiter','cpTier1','cpHRBP','cpAnalytics','cpEthicsLead','cpMarisol','cpNoNewPilots'];
                var cp = [];
                for (var l = 0; l < cpIds.length; l++) {
                    var cc = document.getElementById(cpIds[l]);
                    if (cc && cc.checked) cp.push(cpIds[l]);
                }
                decisions.changePlan = cp;
                return true;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var roundScore = 0;
            var feedback = '';
            var t = (window.mySimulation && window.mySimulation.t)
                ? function(k) { return window.mySimulation.t(k); } : function(k) { return k; };
            var ceoDelta = 0, cooDelta = 0, cfoDelta = 0, boardDelta = 0, councilDelta = 0;
            var killedAny = false;
            var killedP11 = false;
            var killedDuplicate = false;
            var rightCount = 0;

            if (period === 1) {
                ds.pilots = d.pilotChoices || {};
                for (var i = 0; i < this.PILOTS.length; i++) {
                    var p = this.PILOTS[i];
                    var choice = ds.pilots[p.num];
                    if (choice === p.defensible) {
                        roundScore += p.crit ? 4 : 3;
                        rightCount += 1;
                    } else if (choice === 'hold') {
                        roundScore += 0;
                        boardDelta -= 2;
                    } else if (choice === 'kill' && p.defensible !== 'kill') {
                        roundScore += 1;
                    } else {
                        roundScore += 1;
                    }
                    if (choice === 'kill') killedAny = true;
                    if (p.num === 11 && choice === 'kill') killedP11 = true;
                    if ((p.num === 9 || p.num === 10) && choice === 'kill') killedDuplicate = true;
                }
                if (killedP11) { boardDelta += 12; cfoDelta += 6; ceoDelta -= 3; councilDelta += 4; feedback = t('fb_p1_p11_killed'); }
                else { boardDelta -= 10; cfoDelta -= 6; feedback = t('fb_p1_p11_alive'); }
                if (killedDuplicate) { cfoDelta += 6; ceoDelta += 2; }
                else { cfoDelta -= 4; }
                if (!killedAny) { boardDelta -= 8; ceoDelta -= 4; feedback += ' ' + t('fb_p1_none_killed'); }
                if (rightCount >= 9) { ceoDelta += 4; cooDelta += 3; }
                ds.auditScore = Math.round((roundScore / 41) * 100);
                if (ds.auditScore > 100) ds.auditScore = 100;
            }

            else if (period === 2) {
                ds.matrix = d.matrixChoices || {};
                var ledCount = 0, augCount = 0, humanCount = 0;
                var correctLockouts = 0;
                var lockoutCats = [5, 9, 12, 14];
                var ledHits = 0;
                var ledTargets = [1,2,4,11,15,17,18];
                var totalRight = 0;
                for (var j = 0; j < this.MATRIX.length; j++) {
                    var m = this.MATRIX[j];
                    var cc = ds.matrix[m.num];
                    if (cc === 'led') ledCount += 1;
                    else if (cc === 'aug') augCount += 1;
                    else if (cc === 'human') humanCount += 1;
                    if (cc === m.defensible) {
                        roundScore += 3;
                        totalRight += 1;
                        if (lockoutCats.indexOf(m.num) >= 0) correctLockouts += 1;
                        if (ledTargets.indexOf(m.num) >= 0) ledHits += 1;
                    }
                }
                if (ledCount > 11) { ceoDelta += 3; boardDelta -= 12; cooDelta -= 6; feedback = t('fb_p2_led_high'); }
                else if (ledCount < 2) { boardDelta -= 4; cfoDelta -= 10; ceoDelta -= 6; feedback = t('fb_p2_led_low'); }
                else { ceoDelta += 4; cfoDelta += 6; }
                if (correctLockouts === 4) { boardDelta += 14; councilDelta += 12; feedback += ' ' + t('fb_p2_lockouts_correct'); }
                else if (correctLockouts >= 2) { boardDelta += 4; councilDelta += 4; }
                else { boardDelta -= 8; councilDelta -= 8; feedback += ' ' + t('fb_p2_lockouts_thin'); }
                if (ledHits >= 5) { cfoDelta += 6; ceoDelta += 4; cooDelta += 4; }
                if (totalRight >= 15) { ceoDelta += 4; cooDelta += 4; }
                ds.matrixScore = Math.round((roundScore / 57) * 100);
                if (ds.matrixScore > 100) ds.matrixScore = 100;
            }

            else if (period === 3) {
                ds.vendorArch = d.vendorArch || '';
                ds.buildEnvelope = d.buildEnvelope || [];
                ds.changePlan = d.changePlan || [];

                if (ds.vendorArch === 'hub') { roundScore += 25; cfoDelta += 8; ceoDelta += 6; cooDelta += 6; boardDelta += 6; feedback = t('fb_p3_arch_hub'); }
                else if (ds.vendorArch === 'single') { roundScore += 14; cfoDelta += 12; cooDelta -= 4; feedback = t('fb_p3_arch_single'); }
                else if (ds.vendorArch === 'federated') { roundScore += 6; cfoDelta -= 12; boardDelta -= 6; cooDelta -= 6; feedback = t('fb_p3_arch_federated'); }

                var bSize = ds.buildEnvelope.length;
                var bHasPerf = ds.buildEnvelope.indexOf('perf') >= 0;
                var bHasBenefits = ds.buildEnvelope.indexOf('benefits') >= 0;
                if (bSize >= 2 && bSize <= 3) { roundScore += 18; cfoDelta += 4; cooDelta += 4; feedback += ' ' + t('fb_p3_build_bounded'); }
                else if (bSize >= 4 && bSize <= 5) { roundScore += 10; cfoDelta -= 2; }
                else if (bSize >= 6) { roundScore += 4; cfoDelta -= 8; cooDelta -= 4; feedback += ' ' + t('fb_p3_build_unbounded'); }
                else if (bSize === 1) { roundScore += 6; }
                else { roundScore += 2; cooDelta -= 4; }
                if (bHasPerf && bHasBenefits) { roundScore += 4; }

                var cpHas = function(k) { return ds.changePlan.indexOf(k) >= 0; };
                var shrinkNamed = (cpHas('cpRecruiter') ? 1 : 0) + (cpHas('cpTier1') ? 1 : 0);
                if (shrinkNamed === 2) { roundScore += 14; councilDelta += 8; boardDelta += 6; feedback += ' ' + t('fb_p3_change_shrink2'); }
                else if (shrinkNamed === 1) { roundScore += 7; councilDelta += 2; }
                else { councilDelta -= 12; boardDelta -= 6; feedback += ' ' + t('fb_p3_change_shrink0'); }
                if (cpHas('cpEthicsLead')) { roundScore += 4; boardDelta += 4; }
                if (cpHas('cpAnalytics')) { roundScore += 3; ceoDelta += 2; }
                if (cpHas('cpHRBP')) { roundScore += 2; }
                if (cpHas('cpMarisol')) { roundScore += 5; councilDelta += 10; feedback += ' ' + t('fb_p3_change_marisol'); }
                else { councilDelta -= 6; }
                if (cpHas('cpNoNewPilots')) { roundScore += 6; boardDelta += 6; ceoDelta -= 2; feedback += ' ' + t('fb_p3_change_nonewpilots'); }

                ds.archScore = Math.round((roundScore / 79) * 100);
                if (ds.archScore > 100) ds.archScore = 100;
            }

            ds.ceoSupport = Math.max(0, Math.min(100, ds.ceoSupport + ceoDelta));
            ds.cooSupport = Math.max(0, Math.min(100, ds.cooSupport + cooDelta));
            ds.cfoSupport = Math.max(0, Math.min(100, ds.cfoSupport + cfoDelta));
            ds.boardSupport = Math.max(0, Math.min(100, ds.boardSupport + boardDelta));
            ds.councilSupport = Math.max(0, Math.min(100, ds.councilSupport + councilDelta));

            var components = [];
            if (ds.auditScore) components.push(ds.auditScore);
            if (ds.matrixScore) components.push(ds.matrixScore);
            if (ds.archScore) components.push(ds.archScore);
            var avg = components.length ? components.reduce(function(s,v){ return s+v; },0) / components.length : 0;
            var cabinetAvg = (ds.ceoSupport + ds.cooSupport + ds.cfoSupport + ds.boardSupport + ds.councilSupport) / 5;
            ds.totalScore = Math.round(avg * 0.6 + cabinetAvg * 0.4);

            ds.scoreHistory.push(ds.totalScore);

            // v1.1.0 FIX: persist the 0-100 operating-model score so the instructor results panel
            // (results_utils.php express_resolveDomainScore -> domainState.performance.overallScore)
            // shows a real score instead of "-". Additive; scoring logic unchanged.
            ds.performance = { overallScore: ds.totalScore };
            ds.ceoHistory.push(ds.ceoSupport);
            ds.cooHistory.push(ds.cooSupport);
            ds.cfoHistory.push(ds.cfoSupport);
            ds.boardHistory.push(ds.boardSupport);
            ds.councilHistory.push(ds.councilSupport);
            ds.lastFeedback = feedback;

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1 });
                self._updateCabinetBars(ds);
            }, 350);

            return {
                period: period,
                roundScore: roundScore,
                auditScore: ds.auditScore,
                matrixScore: ds.matrixScore,
                archScore: ds.archScore,
                totalScore: ds.totalScore,
                feedback: feedback,
                ceoSupport: ds.ceoSupport,
                cooSupport: ds.cooSupport,
                cfoSupport: ds.cfoSupport,
                boardSupport: ds.boardSupport,
                councilSupport: ds.councilSupport
            };
        }

        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var idx = Math.min(period - 1, 2);
            var titleEl = document.getElementById('roundTitle');
            if (titleEl) {
                titleEl.setAttribute('data-i18n', this.ROUND_TITLES[idx]);
                if (window.mySimulation && window.mySimulation.t) {
                    titleEl.textContent = window.mySimulation.t(this.ROUND_TITLES[idx]);
                }
            }
            var brief = document.getElementById('briefingText');
            if (brief && window.mySimulation && window.mySimulation.t) {
                var keys = ['briefing_r1','briefing_r2','briefing_r3','briefing_done'];
                var k = period > 3 ? keys[3] : keys[idx];
                brief.innerHTML = window.mySimulation.t(k);
            }
            var r1 = document.getElementById('round1Panel');
            var r2 = document.getElementById('round2Panel');
            var r3 = document.getElementById('round3Panel');
            if (r1) r1.style.display = (period === 1) ? 'block' : 'none';
            if (r2) r2.style.display = (period === 2) ? 'block' : 'none';
            if (r3) r3.style.display = (period === 3) ? 'block' : 'none';
        }

        _updateCabinetBars(ds) {
            var pairs = [
                ['ceoBar','ceoPct',ds.ceoSupport],
                ['cooBar','cooPct',ds.cooSupport],
                ['cfoBar','cfoPct',ds.cfoSupport],
                ['boardBar','boardPct',ds.boardSupport],
                ['councilBar','councilPct',ds.councilSupport]
            ];
            for (var i = 0; i < pairs.length; i++) {
                var bar = document.getElementById(pairs[i][0]);
                var pct = document.getElementById(pairs[i][1]);
                var v = pairs[i][2];
                if (bar) {
                    bar.style.width = v + '%';
                    var color = v >= 65 ? 'linear-gradient(90deg, #2d6a4f, #52b788)'
                              : v >= 45 ? 'linear-gradient(90deg, #4a6a8a, #1a2744)'
                              : v >= 25 ? 'linear-gradient(90deg, #c9a14a, #a8841d)'
                              : 'linear-gradient(90deg, #b03030, #8a1f1f)';
                    bar.style.background = color;
                }
                if (pct) pct.textContent = v + '%';
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('totalScoreDisplay', 'domainState.totalScore', function(v) { return v + ''; });
            uiManager.bind('auditScoreDisplay', 'domainState.auditScore', function(v) { return v ? v + '%' : '—'; });
            uiManager.bind('matrixScoreDisplay', 'domainState.matrixScore', function(v) { return v ? v + '%' : '—'; });
            uiManager.bind('archScoreDisplay', 'domainState.archScore', function(v) { return v ? v + '%' : '—'; });
        }

        getChartConfig() {
            return {
                alignmentChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'CEO',     data: [], borderColor: '#1a2744', backgroundColor: 'rgba(26,39,68,0.08)',  borderWidth: 2, tension: 0.2, fill: false },
                            { label: 'COO',     data: [], borderColor: '#4a6a8a', backgroundColor: 'rgba(74,106,138,0.08)',borderWidth: 2, tension: 0.2, fill: false },
                            { label: 'CFO',     data: [], borderColor: '#c9a14a', backgroundColor: 'rgba(201,161,74,0.08)',borderWidth: 2, tension: 0.2, fill: false },
                            { label: 'Board',   data: [], borderColor: '#2d6a4f', backgroundColor: 'rgba(45,106,79,0.08)', borderWidth: 2, tension: 0.2, fill: false },
                            { label: 'Council', data: [], borderColor: '#b03030', backgroundColor: 'rgba(176,48,48,0.08)', borderWidth: 2, tension: 0.2, fill: false }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Cabinet alignment by round', color: '#1a2744' },
                            legend: { position: 'bottom', labels: { color: '#1a2744' } }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100, ticks: { color: '#6b7689' }, grid: { color: '#e6ebf2' } },
                            x: { ticks: { color: '#6b7689' }, grid: { display: false } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.scoreHistory.map(function(_, i) { return 'Round ' + (i + 1); });
            return {
                alignmentChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.ceoHistory },
                        { data: state.domainState.cooHistory },
                        { data: state.domainState.cfoHistory },
                        { data: state.domainState.boardHistory },
                        { data: state.domainState.councilHistory }
                    ]
                }
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.feedback) return results.feedback;
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.period',        label: 'Round',   i18nKey: 'col_round' },
                { key: 'results.totalScore',    label: 'Score',   i18nKey: 'col_score',  formatter: function(v) { return v + ' / 100'; } },
                { key: 'results.ceoSupport',    label: 'CEO',     i18nKey: 'col_ceo',     formatter: function(v) { return v + '%'; } },
                { key: 'results.cooSupport',    label: 'COO',     i18nKey: 'col_coo',     formatter: function(v) { return v + '%'; } },
