        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};
            var total = r.totalScore || 0;
            var t = (window.mySimulation && window.mySimulation.t)
                ? function(k) { return window.mySimulation.t(k); } : function(k) { return k; };
            var performance = t('rating_stage1');
            if (total >= 80) performance = t('rating_stage3');
            else if (total >= 65) performance = t('rating_stage2');
            else if (total >= 45) performance = t('rating_stage15');
            var insights = [];
            insights.push(r.boardSupport >= 65 ? t('insight_board_good') : t('insight_board_bad'));
            insights.push(r.councilSupport >= 60 ? t('insight_council_good') : t('insight_council_bad'));
            insights.push(r.cfoSupport >= 60 ? t('insight_cfo_good') : t('insight_cfo_bad'));
            insights.push(r.ceoSupport >= 60 ? t('insight_ceo_good') : t('insight_ceo_bad'));
            return {
                overallScore: total,
                totalScore: total,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var t = (window.mySimulation && window.mySimulation.t)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            summary = summary || {};
            var score = (summary.overallScore != null) ? summary.overallScore
                        : (summary.totalScore != null ? summary.totalScore : null);
            var rating = summary.performance || '';
            var insights = Array.isArray(summary.insights) ? summary.insights : [];
            var items = insights.map(function(s) { return '<li>' + s + '</li>'; }).join('');
            var scoreBlock = (score != null)
                ? '<div class="hrai-completion-score"><span class="acs-num">' + score
                    + '</span><span class="acs-max">/100</span><div class="acs-cap">'
                    + t('complete_score') + '</div></div>'
                : '';
            return ''
                + '<div class="hrai-completion">'
                +   '<h3 class="hrai-completion-title">' + t('complete_title') + '</h3>'
                +   scoreBlock
                +   (rating ? '<p class="hrai-completion-rating">' + t('complete_rating') + ': ' + rating + '</p>' : '')
                +   (items ? '<div class="hrai-completion-takeaways"><h4>' + t('complete_takeaways')
                        + '</h4><ul>' + items + '</ul></div>' : '')
                +   '<p class="hrai-completion-thanks">' + t('complete_thanks') + '</p>'
                + '</div>';
        }

